head.script:
(function(){
  const TK="current_theme",FK="current_font";
  window.applyVtheme=()=>new Promise(r=>{
    const isAlt=localStorage.getItem("is_alt_theme")==="true";
    const alt=document.getElementById("theme-alt");
    if(alt) alt.media=isAlt?"":"not all";
    document.documentElement.setAttribute("data-theme",localStorage.getItem(TK)||"vapor");
    r();
  });
  window.applyVfont=()=>{
    const f=localStorage.getItem(FK);
    let s=document.getElementById("dyn-font");
    if(!f||f.trim()===""||f.toLowerCase()==="default"){if(s)s.remove();return;}
    const u="https://fonts.googleapis.com/css2?family="+f.replace(/ /g,"+")+":wght@400;700&display=swap";
    if(!s){s=document.createElement("style");s.id="dyn-font";document.head.appendChild(s);}
    s.innerHTML="@import url('"+u+"');*{font-family:'"+f+"',sans-serif!important}";
  };
  applyVtheme();applyVfont();
  window.addEventListener("storage",e=>{if(e.key===TK)applyVtheme();if(e.key===FK)applyVfont();});
})();
